import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"21、【噬嗑】 震下离上","description":"横渠易说 - 21、【噬嗑】 震下离上","frontmatter":{"title":"21、【噬嗑】 震下离上","description":"横渠易说 - 21、【噬嗑】 震下离上"},"headers":[],"relativePath":"zh/classics/hengqu/023.md","filePath":"zh/classics/hengqu/023.md"}'),l={name:"zh/classics/hengqu/023.md"};function t(n,a,s,d,c,o){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_21、【噬嗑】-震下离上" tabindex="-1">21、【噬嗑】 震下离上 <a class="header-anchor" href="#_21、【噬嗑】-震下离上" aria-label="Permalink to “21、【噬嗑】 震下离上”">​</a></h1><h3 id="彖曰-颐中有物曰噬嗑。噬嗑而亨-刚柔分-动而明-雷电合而章-柔得中而上行-虽不当位-利用狱也。" tabindex="-1">彖曰：颐中有物曰噬嗑。噬嗑而亨，刚柔分，动而明，雷电合而章，柔得中而上行，虽不当位，利用狱也。 <a class="header-anchor" href="#彖曰-颐中有物曰噬嗑。噬嗑而亨-刚柔分-动而明-雷电合而章-柔得中而上行-虽不当位-利用狱也。" aria-label="Permalink to “彖曰：颐中有物曰噬嗑。噬嗑而亨，刚柔分，动而明，雷电合而章，柔得中而上行，虽不当位，利用狱也。”">​</a></h3><p>子路礼乐文章未足尽为政之道，以其重然诺，言为众信，故片言可以折狱。如易“利用狱”，“利用刑人”，皆非卦爻盛德，适能是而已焉</p><p>九五分而下，初六分而上，故曰“刚柔分”。“合而章”，合而成文也。</p><h3 id="象曰-雷电-噬嗑-先王以明罚法。" tabindex="-1">象曰：雷电，噬嗑，先王以明罚法。 <a class="header-anchor" href="#象曰-雷电-噬嗑-先王以明罚法。" aria-label="Permalink to “象曰：雷电，噬嗑，先王以明罚法。”">​</a></h3><p>六自初而进之于五，故曰“上行”。</p><h3 id="初九-屦校灭趾-无咎。-象曰-屦校灭趾-不行也。" tabindex="-1">初九，屦校灭趾，无咎。 象曰：“屦校灭趾”，不行也。 <a class="header-anchor" href="#初九-屦校灭趾-无咎。-象曰-屦校灭趾-不行也。" aria-label="Permalink to “初九，屦校灭趾，无咎。 象曰：“屦校灭趾”，不行也。”">​</a></h3><p>戒之在初，小惩可止，故无咎。</p><h3 id="六二-噬肤灭鼻-无咎。-象曰-噬肤灭鼻-乘刚也。" tabindex="-1">六二，噬肤灭鼻，无咎。 象曰：“噬肤灭鼻”，乘刚也。 <a class="header-anchor" href="#六二-噬肤灭鼻-无咎。-象曰-噬肤灭鼻-乘刚也。" aria-label="Permalink to “六二，噬肤灭鼻，无咎。 象曰：“噬肤灭鼻”，乘刚也。”">​</a></h3><p>六三居有过之地而己噬之，乘刚而动，为力不劳，动未过中，故无咎。</p><h3 id="六三-噬腊肉遇毒-小吝无咎。-象曰-遇毒-位不当也。" tabindex="-1">六三，噬腊肉遇毒，小吝无咎。 象曰：“遇毒”，位不当也。 <a class="header-anchor" href="#六三-噬腊肉遇毒-小吝无咎。-象曰-遇毒-位不当也。" aria-label="Permalink to “六三，噬腊肉遇毒，小吝无咎。 象曰：“遇毒”，位不当也。”">​</a></h3><p>所间在四，四为刚阳，故曰“腊肉”；非礼伤义，故曰“遇毒”。能以为毒而舍之，虽近不相得，小有吝而无咎也。</p><h3 id="九四-噬乾胏-得金矢-利艰贞-吉。-象曰-利艰贞吉-未光也。" tabindex="-1">九四，噬乾胏，得金矢，利艰贞，吉。 象曰：“利艰贞吉”，未光也。 <a class="header-anchor" href="#九四-噬乾胏-得金矢-利艰贞-吉。-象曰-利艰贞吉-未光也。" aria-label="Permalink to “九四，噬乾胏，得金矢，利艰贞，吉。 象曰：“利艰贞吉”，未光也。”">​</a></h3><p>五为阴柔，故喻乾胏；能守正得刚直之义，故艰贞吉，其德光大则其正非艰也。</p><h3 id="六五-噬乾肉-得黄金-贞厉无咎。-象曰-贞厉无咎-得当也。" tabindex="-1">六五，噬乾肉，得黄金，贞厉无咎。 象曰：“贞厉无咎”，得当也。 <a class="header-anchor" href="#六五-噬乾肉-得黄金-贞厉无咎。-象曰-贞厉无咎-得当也。" aria-label="Permalink to “六五，噬乾肉，得黄金，贞厉无咎。 象曰：“贞厉无咎”，得当也。”">​</a></h3><h3 id="上九-何校灭耳-凶。-象曰-何校灭耳-聪不明也。" tabindex="-1">上九，何校灭耳，凶。 象曰：“何校灭耳”，聪不明也。 <a class="header-anchor" href="#上九-何校灭耳-凶。-象曰-何校灭耳-聪不明也。" aria-label="Permalink to “上九，何校灭耳，凶。 象曰：“何校灭耳”，聪不明也。”">​</a></h3><p>九四、</p><h3 id="上九-难于屈服-故曰-乾肉-。得居中持坚之义-正而危则得无咎也。" tabindex="-1">上九，难于屈服，故曰“乾肉”。得居中持坚之义，正而危则得无咎也。 <a class="header-anchor" href="#上九-难于屈服-故曰-乾肉-。得居中持坚之义-正而危则得无咎也。" aria-label="Permalink to “上九，难于屈服，故曰“乾肉”。得居中持坚之义，正而危则得无咎也。”">​</a></h3>',18)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
